import sys, time, threading
sys.path.insert(0, sys.argv[1])
from counter import Counter


class Store:
    def __init__(self, delay):
        self.delay = delay

    def record_visit(self):
        time.sleep(self.delay)  # I/O stand-in; yields the GIL


def run(delay, threads=8, per=50, lock=None):
    c = Counter(Store(delay))

    def w():
        for _ in range(per):
            if lock:
                with lock:
                    c.hit()
            else:
                c.hit()

    ts = [threading.Thread(target=w) for _ in range(threads)]
    [t.start() for t in ts]
    [t.join() for t in ts]
    return c.count, threads * per


for d in (0, 0.0001):
    got, want = run(d)
    print(f"store_delay={d} count={got} expected={want} {'RED' if got != want else 'green'}")
print("single-thread:", run(0.0001, threads=1, per=400))
print("externally-locked:", run(0.0001, lock=threading.Lock()))

